      "record_ids": ["S02-00100", "S02-00104", "S02-00108", "S02-00115"]
    }
  ],
  "known_telemetry_limitations": [
    "The available evidence is limited to the listed Sysmon, Windows security, proxy, DNS, connection, and TLS log sources for the specified review window.",
